	const cases = [
		[1, "I"],
		[4, "IV"],
		[9, "IX"],
		[14, "XIV"],
		[40, "XL"],
		[90, "XC"],
		[400, "CD"],
		[1994, "MCMXCIV"],
		[3999, "MMMCMXCIX"],
	];
	for (const [n, roman] of cases) assert.equal(toRoman(n), roman);
});

test("rejects numbers outside 1 to 3999 with a RangeError", () => {
	assert.throws(() => toRoman(0), RangeError);
	assert.throws(() => toRoman(4000), RangeError);
});

