// Convert a whole number from 1 to 3999 to a Roman numeral.
export function toRoman(n) {
	if (!Number.isInteger(n) || n < 1 || n > 3999) {
		throw new RangeError("n must be a whole number between 1 and 3999");
	}
	const table = [
		[1000, "M"],
		[900, "CM"],
		[500, "D"],
		[400, "CD"],
		[100, "C"],
		[90, "XC"],
		[50, "L"],
		[40, "XL"],
		[10, "X"],
		[9, "IX"],
		[5, "V"],
		[4, "IV"],
		[1, "I"],
	];
	let result = "";
	let remaining = n;
	for (const [value, symbol] of table) {
		while (remaining >= value) {
			result += symbol;
			remaining -= value;
		}
	}
	return result;
}
